# frozen_string_literal: true

# The generated files of the pure-Ruby prism, and a check of the vendored
# gem's own. Both render from prism 1.9.0's config.yml with the locals of
# its template driver (vendor/ext/prism/templates/template.rb):
#
# * zr's templates (test/support/oracle/prism/templates/*.rb.erb) render into
#   runtime/ext/prism/ruby/*.rb;
# * upstream's templates (vendor/ext/prism/templates/lib) must render the
#   vendored vendor/ext/prism/lib files byte for byte. Vendored files are
#   never written; a difference fails.
#
#   rake gen:prism_generate             writes zr's generated files
#   rake 'gen:prism_generate[--check]'  writes nothing, and fails on a
#                                       stale or differing file
require "erb"
require "fileutils"
require "tmpdir"

module PrismGenerate
  ROOT = File.expand_path("../../..", __dir__)
  UPSTREAM = File.join(ROOT, "vendor/ext/prism")
  TEMPLATES = File.join(ROOT, "test/support/oracle/prism/templates")
  OUT = File.join(ROOT, "runtime/ext/prism/ruby")

  module_function

  def driver
    load File.join(UPSTREAM, "templates/template.rb") unless defined?(Prism::Template)
    Prism::Template
  end

  # Upstream's rendered files that differ from the vendored ones.
  def upstream_differences
    Dir.mktmpdir("prism-generate-") do |dir|
      Dir.glob("lib/**/*.rb.erb", base: File.join(UPSTREAM, "templates")).sort.filter_map do |erb|
        name = erb.delete_suffix(".erb")
        rendered = File.join(dir, name)
        driver.render(name, write_to: rendered)
        name unless FileUtils.identical?(rendered, File.join(UPSTREAM, name))
      end
    end
  end

  # Each of zr's templates rendered: `{ path => text }`. A template sees
  # config.yml's locals and `upstream`, the vendored templates directory.
  def ours
    locals = driver.send(:locals).merge(upstream: File.join(UPSTREAM, "templates"))
    Dir.glob("*.rb.erb", base: TEMPLATES).sort.to_h do |erb|
      path = File.join(TEMPLATES, erb)
      template = ERB.new(File.read(path), trim_mode: "-")
      template.filename = path
      heading = <<~RUBY
        # frozen_string_literal: true
        # shareable_constant_value: literal

        # Generated by `rake gen:prism_generate` from
        # test/support/oracle/prism/templates/#{erb}
        # and prism 1.9.0's config.yml. Do not edit.

      RUBY
      [File.join(OUT, erb.delete_suffix(".erb")), heading + template.result_with_hash(locals)]
    end
  end
end

check = ARGV.include?("--check")
failures = PrismGenerate.upstream_differences.map { |name| "vendored #{name} differs from its template" }
PrismGenerate.ours.each do |path, text|
  next if File.exist?(path) && File.read(path) == text

  if check
    failures << "#{path.delete_prefix("#{PrismGenerate::ROOT}/")} is stale (run rake gen:prism_generate)"
  else
    File.write(path, text)
    puts "wrote #{path.delete_prefix("#{PrismGenerate::ROOT}/")}"
  end
end
abort failures.join("\n") unless failures.empty?
puts "current" if check
